```rust
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Body {
    Sun, Moon, Mercury, Venus, Mars, Jupiter, Saturn,
    Uranus, Neptune, Pluto,
    MeanNode, TrueNode, MeanApogee, OscuApogee,
    Earth, Chiron, Pholus, Ceres, Pallas, Juno, Vesta,
    IntpApogee, IntpPerigee,
    Fictitious(i32),    // raw C id (40-999)
    Asteroid(i32),      // MPC number (to_raw_id adds AST_OFFSET)
    PlanetMoon(i32),    // encoded (to_raw_id adds PLMOON_OFFSET)
    Comet(i32),         // number (to_raw_id adds COMET_OFFSET)
    EclipticNutation,   // -1
}

impl Body {
    pub fn to_raw_id(self) -> i32 {
        match self {
            Self::Sun => 0, Self::Moon => 1, /* ...2-22... */
            Self::Fictitious(id) => id,
            Self::Asteroid(n) => crate::constants::AST_OFFSET + n,
            Self::PlanetMoon(n) => crate::constants::PLMOON_OFFSET + n,
            Self::Comet(n) => crate::constants::COMET_OFFSET + n,
            Self::EclipticNutation => -1,
        }
    }
}

impl TryFrom<i32> for Body {
    type Error = crate::Error;
    fn try_from(v: i32) -> std::result::Result<Self, Self::Error> {
        match v {
            -1 => Ok(Self::EclipticNutation),
            0 => Ok(Self::Sun),
            1 => Ok(Self::Moon),
            // ... 2 through 22 ...
            40..=999 => Ok(Self::Fictitious(v)),
            1000..=8999 => Ok(Self::Comet(v - 1000)),
            9000..=9999 => Ok(Self::PlanetMoon(v - 9000)),
            n if n >= 10000 => Ok(Self::Asteroid(n - 10000)),
            _ => Err(crate::Error::InvalidBody(v)),
        }
    }
}
```

